\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath,amssymb,amsthm,booktabs,enumitem,microtype,hyperref}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{example}[theorem]{Example}
\title{Symmetry Quotients and the Information Capacity\\of Periodic Rhythmic Patterns}
\author{Aristotle}
\date{July 19, 2026}
\begin{document}
\maketitle

\begin{abstract}
Periodic musical data can be represented by binary labelings of a finite time, pitch, or instrument grid. Geometric or structural symmetries identify cells and require their labels to agree. For an arbitrary equivalence relation, invariant binary patterns are in bijection with Boolean functions on the quotient. Consequently, a finite grid with $m$ symmetry classes admits exactly $2^m$ invariant patterns and has uniform binary information capacity $m$ bits. An injective comparison of quotient spaces gives monotonicity: increasing identifications cannot increase the admissible pattern count. Under maximal symmetry on any nonempty finite grid, precisely two patterns remain, complete silence and complete saturation. We present algorithms for orbit construction, enumeration, sampling, verification, and compression, and explain the relation to finite models of wallpaper symmetry. The exact counting results are distinguished from the untested conjecture that the seventeen planar wallpaper groups define seventeen musically fundamental rhythmic types.
\end{abstract}

\section{Introduction}
A periodic binary rhythm is a function $f:\mathbb Z\to\{0,1\}$ satisfying $f(n+p)=f(n)$ for some positive period $p$. It is determined by a finite cyclic word. Musical representations naturally add a second coordinate: drum-machine grids use time and instrumental voice, piano rolls use time and pitch, and polyrhythmic diagrams may use pulse and phase. Such data are binary patterns on a finite grid whose repetition suggests a planar tiling.

Periodic planar geometry includes translations, rotations, reflections, and glide reflections. The classical crystallographic classification gives exactly seventeen wallpaper-group types. This motivates a musical question: can rhythmic organization be classified by those symmetries? A necessary first step is more basic and precise. Given a finite cell set and specified identifications among its cells, how many binary patterns respect the identifications, and how much independent information can they carry?

The answer depends only on the number of equivalence classes. If there are $m$ classes, an invariant pattern makes one binary choice per class, giving $2^m$ patterns. This quotient formulation applies uniformly to group orbits, mirror pairings, periodic boundaries, and relations generated by several transformations.

\section{Framework}
\subsection{Periodic grids}
A two-dimensional periodic pattern is a function $g:\mathbb Z^2\to\{0,1\}$ invariant under translations by a rank-two lattice. A fundamental region gives a finite labeling. A common sampled model is the torus
\[
X=(\mathbb Z/p\mathbb Z)\times(\mathbb Z/q\mathbb Z),
\]
where the coordinates may represent time and pitch, voice, or phase. The main arguments require no coordinates and apply to an arbitrary set $X$.

\begin{definition}[Cell equivalence]
An equivalence relation $\sim$ on $X$ is reflexive, symmetric, and transitive. The class of $x$ is $[x]=\{y\in X:y\sim x\}$, and $X/{\sim}$ is the set of all classes.
\end{definition}

Transformations generate an equivalence relation by placing two cells in the same class exactly when one can be transformed into the other. Pairwise musical constraints may instead be closed under the three equivalence laws; a group action is not required.

\begin{definition}[Invariant binary pattern]
A binary pattern is a function $f:X\to\{0,1\}$. It is invariant under $\sim$ when $x\sim y$ implies $f(x)=f(y)$. Write $\mathcal I(X,{\sim})$ for the set of invariant patterns.
\end{definition}

\begin{definition}[Quotient labeling]
A quotient labeling is an arbitrary function $\varphi:X/{\sim}\to\{0,1\}$.
\end{definition}

An invariant pattern labels every original cell subject to consistency constraints; a quotient labeling records only independent choices.

\begin{definition}[Uniform binary capacity]
For a finite pattern family $\mathcal P$, define $C(\mathcal P)=\log_2|\mathcal P|$. This support-size quantity equals Shannon entropy only for the uniform distribution.
\end{definition}

\section{Quotient representation}
\begin{theorem}[Quotient Representation Theorem]
For any set $X$ with equivalence relation $\sim$, quotient labelings $X/{\sim}\to\{0,1\}$ are in bijection with invariant binary patterns on $X$.
\end{theorem}
\begin{proof}
Given $\varphi$, define $(P\varphi)(x)=\varphi([x])$. Equivalent cells have equal classes, so $P\varphi$ is invariant. Conversely, for invariant $f$, define $(Qf)([x])=f(x)$. If two representatives define the same class, they are equivalent and invariance makes their values equal, so $Qf$ is well defined. Direct substitution gives $Q(P\varphi)=\varphi$ and $P(Qf)=f$. Thus $P$ and $Q$ are inverse maps.
\end{proof}

\begin{corollary}[Quotient Extension Uniqueness]
If two invariant patterns induce the same value on every quotient class, then they agree on every cell.
\end{corollary}
\begin{proof}
For each $x\in X$, both pattern values equal the common label of $[x]$.
\end{proof}

The same argument works for any label set $A$: invariant functions $X\to A$ correspond to functions $X/{\sim}\to A$.

\section{Counting and monotonicity}
\begin{theorem}[Symmetry--Entropy Counting Theorem]
Let $X$ be finite and let $|X/{\sim}|=m$. Then
\[
|\mathcal I(X,{\sim})|=2^m,
\qquad C(\mathcal I(X,{\sim}))=m\text{ bits}.
\]
\end{theorem}
\begin{proof}
By the Quotient Representation Theorem, invariant patterns correspond to Boolean functions on an $m$-element set. Each quotient cell independently receives one of two labels, so the multiplication principle gives $2^m$ functions. Taking $\log_2$ gives $m$.
\end{proof}

If $N=|X|$, then $m\leq N$. Equality holds with no nontrivial identifications, producing all $2^N$ patterns. Each reduction of the orbit count by one halves the admissible family.

\begin{theorem}[Quotient Monotonicity]
Let $\sim_s$ and $\sim_t$ be equivalence relations on the same finite set. If an injection $X/{\sim_t}\hookrightarrow X/{\sim_s}$ exists, then
\[
|\mathcal I(X,{\sim_t})|\leq |\mathcal I(X,{\sim_s})|.
\]
\end{theorem}
\begin{proof}
The injection gives $|X/{\sim_t}|\leq|X/{\sim_s}|$. Since $m\mapsto2^m$ is increasing, the counting theorem yields the result.
\end{proof}

The explicit quotient condition avoids ambiguity in the phrase ``more symmetric.'' Distinct groups need not be ordered by inclusion and may induce orbit structures that differ geometrically while having equal cardinality.

\begin{definition}[Maximal cell equivalence]
The maximal relation declares $x\sim y$ for every $x,y\in X$.
\end{definition}

\begin{theorem}[Maximal-Symmetry Theorem]
On every nonempty finite cell set with maximal equivalence, exactly two invariant binary patterns exist: complete silence and an onset in every cell.
\end{theorem}
\begin{proof}
The nonempty quotient has one class, so the count is $2^1=2$. The shared class label is either zero or one.
\end{proof}

Nonemptiness is essential: the empty set has one binary labeling and no quotient classes.

\section{Algorithms}
Let $X=\{0,\ldots,N-1\}$ and suppose $E$ input pairs must be equivalent. A disjoint-set union structure computes the classes. Initially every cell is separate; each pair merges two classes. Path compression and union by rank require $O((N+E)\alpha(N))$ amortized time and $O(N)$ memory, where $\alpha$ is the inverse Ackermann function. For $k$ transformation generators, adding $(x,T_i(x))$ for each cell and generator produces at most $kN$ merge requests.

After finding classes $C_0,\ldots,C_{m-1}$, enumeration runs through masks $0\leq r<2^m$, uses bit $j$ as the label of $C_j$, and expands labels to all cells. Materializing all outputs costs $O(N2^m)$ time and $O(N+m)$ working memory beyond stored output; exponential time is unavoidable because there are $2^m$ answers.

Uniform generation is cheaper. Draw $m$ fair bits and copy each class bit to its cells. It uses exactly $m$ random bits and $O(N+m)$ time. The quotient bijection proves uniformity over invariant patterns. Invariance testing takes $O(N)$ time after class membership is known: compare every cell with a reference value for its class.

For compression, store one bit per class rather than one per cell. Reconstruction copies each class bit to all its members. Data size falls from $N$ to $m$ bits, excluding the description cost of the symmetry relation. Quotient Extension Uniqueness proves lossless reconstruction within the invariant family.

\section{Examples}
\begin{example}[Sixteen-step loop]
With equality as the relation, a sixteen-step loop has $m=16$ classes and $2^{16}=65{,}536$ patterns. Its capacity is $16$ bits.
\end{example}

\begin{example}[Mirror symmetry]
Identify step $i$ with step $15-i$. The eight pairs form eight classes, giving $2^8=256$ patterns and $8$ bits of capacity. The first eight values determine the rest.
\end{example}

\begin{example}[Half-turn on a $4\times4$ torus]
Identify $(i,j)$ with $(-i,-j)$ in $(\mathbb Z/4\mathbb Z)^2$. Four cells, with coordinates in $\{0,2\}$, are fixed. The other twelve form six pairs. Thus $m=10$ and there are $2^{10}=1{,}024$ invariant patterns. Fixed points show why group order alone does not determine orbit count.
\end{example}

\begin{example}[Row-constant grid]
On four voices and sixteen times, identify all positions within each voice. Four classes give $2^4=16$ patterns. Identifying the voices as well leaves maximal symmetry and two patterns.
\end{example}

Two geometrically different relations can have the same $m$ and hence the same capacity. Capacity measures independent binary choices, not their spatial arrangement or perceptual effect.

\section{Wallpaper symmetry and music}
A wallpaper group is a discrete group of Euclidean-plane isometries with compact fundamental region. Such groups contain translations and may include rotations of orders $2$, $3$, $4$, or $6$, reflections, and glide reflections. Exactly seventeen crystallographic types occur.

A finite group action on musical cells induces $x\sim_G y$ when $y=g\cdot x$ for some $g$. The results above then state
\[
|\mathcal I(X,{\sim_G})|=2^{|X/G|}.
\]
Several distinctions are crucial. An infinite wallpaper group need not act on every finite rectangular sample; a transformation must preserve the sampling lattice and boundary identifications to descend to a torus. The group used to generate a pattern may be smaller than the full stabilizer of a special labeling. Moreover, musical notions such as canon, round, palindrome, and blues involve timing, voice entry, harmony, and perception. Geometric resemblance does not establish their equivalence to crystallographic types.

Accordingly, the proposition that music has exactly seventeen fundamental rhythmic types is a conjectural interpretation, not a consequence of planar classification or the counting theorem. The exact statement is conditional: for every specified symmetry relation on a finite musical grid, quotient size determines invariant-pattern count and uniform capacity.

\section{Applications}
In generative composition, transformations determine dependencies and quotient bits determine content. Orbit count is a complexity control: decreasing $m$ by one halves the admissible family. In corpus analysis, the factor $2^{m_1-m_2}$ gives the ratio of support sizes for models with $m_1$ and $m_2$ classes, providing a combinatorial baseline for frequency comparisons. In compression, a shared symmetry permits storage of $m$ onset bits instead of $N$.

The model also has pedagogical value. It makes the connection among group actions, equivalence relations, combinatorics, and information theory visible and audible. Yet orbit count is not a complete musical-complexity measure: equal-capacity relations may differ in locality, accent, voice leading, and perceptual salience.

\section{Limitations and future work}
The theory treats exact binary invariance. It does not model velocity, duration, microtiming, timbre, approximate symmetry, or perceptual grouping. For an alphabet of size $a$, the same proof gives $a^m$ invariant labelings. The value $m$ is support capacity, not empirical Shannon entropy; nonuniform or correlated use of quotient labels lowers probabilistic entropy.

No corpus or classification protocol is assumed, so no empirical distribution among the seventeen wallpaper types is asserted. A reproducible study requires MIDI encoding, quantization, tolerance rules, boundary conventions, symmetry detection, and a statistical null model.

Future work should formulate explicit finite group actions and use Burnside's lemma
\[
|X/G|=\frac1{|G|}\sum_{g\in G}|\operatorname{Fix}(g)|
\]
to derive capacities from fixed-point counts. Further priorities include faithful models of planar isometries and lattices; determining which symmetries descend to $(\mathbb Z/p\mathbb Z)\times(\mathbb Z/q\mathbb Z)$; distinguishing ambient groups from pattern stabilizers; developing Shannon-entropy bounds; and defining falsifiable musical predicates for canons, rounds, and palindromes.

\section{Conclusion}
Symmetry constrains a binary rhythm by identifying cells. The quotient records exactly the independent choices that remain. Invariant patterns correspond bijectively to quotient labelings, so a finite quotient of size $m$ supports $2^m$ patterns and $m$ bits of uniform capacity. Quotient injections give monotonicity, while maximal symmetry on a nonempty grid leaves silence and saturation alone. These results support generation, compression, and statistical baselines while clearly separating established combinatorics from the proposed musical interpretation of the seventeen wallpaper groups.

\end{document}

