from __future__ import annotations
from itertools import product

def mirror_patterns(length: int) -> list[tuple[int, ...]]:
    classes = [{i, length - 1 - i} for i in range((length + 1) // 2)]
    unique = []
    for group in classes:
        if group not in unique:
            unique.append(group)
    output = []
    for labels in product((0, 1), repeat=len(unique)):
        row = [0] * length
        for group, bit in zip(unique, labels):
            for i in group: row[i] = bit
        output.append(tuple(row))
    return output

if __name__ == "__main__":
    patterns = mirror_patterns(16)
    print("mirror classes = 8")
    print("patterns =", len(patterns), "= 2^8")
    print("sample =", patterns[73])

from __future__ import annotations

def capacity(class_count: int) -> tuple[int, int]:
    if class_count < 0: raise ValueError("class_count must be nonnegative")
    return 2 ** class_count, class_count

if __name__ == "__main__":
    for m in range(16, 0, -1):
        count, bits = capacity(m)
        print(f"{m:2} classes | {count:6} patterns | {bits:2} bits")
    print("Each merger that lowers m by one halves the pattern count.")

