from __future__ import annotations
from typing import Iterable

def quotient_classes(n: int, pairs: Iterable[tuple[int, int]]) -> list[list[int]]:
    parent=list(range(n)); rank=[0]*n
    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]; x = parent[x]
        return x
    for a,b in pairs:
        a,b=find(a),find(b)
        if a == b: continue
        if rank[a] < rank[b]: a,b=b,a
        parent[b]=a
        if rank[a] == rank[b]: rank[a]+=1
    groups: dict[int,list[int]]={}
    for x in range(n): groups.setdefault(find(x),[]).append(x)
    return list(groups.values())

from __future__ import annotations
from itertools import product
from typing import Iterator, Sequence

def enumerate_invariant(n: int, classes: Sequence[Sequence[int]]) -> Iterator[tuple[int,...]]:
    for labels in product((0,1), repeat=len(classes)):
        pattern=[0]*n
        for orbit,bit in zip(classes,labels):
            for cell in orbit: pattern[cell]=bit
        yield tuple(pattern)

from __future__ import annotations
from random import Random
from typing import Sequence

def sample_invariant(n: int, classes: Sequence[Sequence[int]], seed: int=0) -> tuple[int,...]:
    rng=Random(seed); pattern=[0]*n
    for orbit in classes:
        bit=rng.randrange(2)
        for cell in orbit: pattern[cell]=bit
    return tuple(pattern)

def compress_invariant(pattern: Sequence[int], classes: Sequence[Sequence[int]]) -> tuple[int,...]:
    labels=[]
    for orbit in classes:
        values={pattern[i] for i in orbit}
        if len(values) != 1: raise ValueError("pattern is not invariant")
        labels.append(values.pop())
    return tuple(labels)

